TLM.f("Tempora/Pasc5-5",{"officium":"Feria VI infra Octavam Ascensionis","rule":["Evangelium non appropriatum","ex Tempora/Pasc5-4;","Gloria","Suffr=Maria3;Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Asc","Gloria","Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"fallback":"Tempora/Pasc5-4","from":{"Introitus":"Tempora/Pasc5-4","Oratio":"Tempora/Pasc5-4","Lectio":"Tempora/Pasc5-4","Graduale":"Tempora/Pasc5-4","Evangelium":"Tempora/Pasc5-4","Offertorium":"Tempora/Pasc5-4","Secreta":"Tempora/Pasc5-4","Communio":"Tempora/Pasc5-4","Postcommunio":"Tempora/Pasc5-4"},"sections":{"Introitus":[{"k":"ref","la":"Acta 1:11"},{"k":"text","la":"Viri Galilǽi, quid admirámini aspiciéntes in cœlum? allelúja: quemádmodum vidístis eum ascendéntem in cœlum, ita véniet, allelúja, allelúja, allelúja."},{"k":"ref","la":"Ps 46:2"},{"k":"text","la":"Omnes gentes, pláudite mánibus: jubiláte Deo in voce exsultatiónis."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Viri Galilǽi, quid admirámini aspiciéntes in cœlum? allelúja: quemádmodum vidístis eum ascendéntem in cœlum, ita véniet, allelúja, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut, qui hodiérna die Unigénitum tuum, Redemptórem nostrum, ad cœlos ascendísse crédimus; ipsi quoque mente in cœléstibus habitémus."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostólorum"},{"k":"ref","la":"Act 1:1-11"},{"k":"text","la":"Primum quidem sermónem feci de ómnibus, o Theóphile, quæ cœpit Jesus facere et docére usque in diem, qua, præcípiens Apóstolis per Spíritum Sanctum, quos elégit, assúmptus est: quibus et prǽbuit seípsum vivum post passiónem suam in multas arguméntis, per dies quadragínta appárens eis et loquens de regno Dei. Et convéscens, præcépit eis, ab Jerosólymis ne discéderent, sed exspectárent promissiónem Patris, quam audístis -inquit - per os meum: quia Joánnes quidem baptizávit aqua, vos autem baptizabímini Spíritu Sancto non post multos hos dies. Igitur qui convénerant, interrogábant eum, dicéntes: Dómine, si in témpore hoc restítues regnum Israël? Dixit autem eis: Non est vestrum nosse témpora vel moménta, quæ Pater pósuit in sua potestáte: sed accipiétis virtútem superveniéntis Spíritus Sancti in vos, et éritis mihi testes in Jerúsalem et in omni Judǽa et Samaría et usque ad últimum terræ. Et cum hæc dixísset, vidéntibus illis, elevátus est, et nubes suscépit eum ab óculis eórum. Cumque intueréntur in cœlum eúntem illum, ecce, duo viri astitérunt juxta illos in véstibus albis, qui et dixérunt: Viri Galilǽi, quid statis aspiciéntes in cœlum? Hic Jesus, qui assúmptus est a vobis in cœlum, sic véniet, quemádmodum vidístis eum eúntem in cœlum."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 46:6"},{"k":"text","la":"Ascéndit Deus in jubilatióne, et Dóminus in voce tubæ. Allelúja."},{"k":"ref","la":"Ps 67:18-19"},{"k":"text","la":"Dóminus in Sina in sancto, ascéndens in altum, captívam duxit captivitátem. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum."},{"k":"ref","la":"Marc 16:14-20"},{"k":"text","la":"In illo témpore: Recumbéntibus úndecim discípulis, appáruit illis Jesus: et exprobrávit incredulitátem eórum et durítiam cordis: quia iis, qui víderant eum resurrexísse, non credidérunt. Et dixit eis: Eúntes in mundum univérsum, prædicáte Evangélium omni creatúræ. Qui credíderit et baptizátus fúerit, salvus erit: qui vero non credíderit, condemnábitur. Signa autem eos, qui credíderint, hæc sequéntur: In nómine meo dæmónia ejícient: linguis loquentur novis: serpentes tollent: et si mortíferum quid bíberint, non eis nocébit: super ægros manus impónent, et bene habébunt. Et Dóminus quidem Jesus, postquam locútus est eis, assúmptus est in cœlum, et sedet a dextris Dei. Illi autem profécti, prædicavérunt ubíque, Dómino cooperánte et sermónem confirmánte, sequéntibus signis."},{"k":"rubric","la":"Dicto Evangelio exstinguitur Cereus paschalis."}],"Offertorium":[{"k":"ref","la":"Ps 46:6"},{"k":"text","la":"Ascéndit Deus in jubilatióne, et Dóminus in voce tubæ, allelúja."}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, múnera, quæ pro Fílii tui gloriósa Ascensióne deférimus: et concéde propítius; ut a præséntibus perículis liberémur, et ad vitam perveniámus ætérnam."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Ps 67:33-34"},{"k":"text","la":"Psállite Dómino, qui ascéndit super cœlos cœlórum ad Oriéntem, allelúja."}],"Postcommunio":[{"k":"text","la":"Præsta nobis, quǽsumus, omnípotens et miséricors Deus: ut, quæ visibílibus mystériis suménda percépimus, invisíbili consequámur efféctu."},{"k":"macro","name":"Per Dominum"}]},"hr":{"11321165d300c525":{"t":"Dj 1, 11, Ps 46, 2\n(Dj 1, 11) Galilejci, što se čudite gledajući na nebo, <i>aleluja</i>?\nKao što ste vidjeli da on uzlazi na nebo tako će i doći, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 46, 2) Svi narodi plješćite rukama, kličite Bogu radosnim glasom.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Dj 1, 11) Galilejci, što se čudite gledajući na nebo, <i>aleluja</i>?\nKao što ste vidjeli da on uzlazi na nebo tako će i doći, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Dj. Ap. 1, 11). Ljudi Galilejci, što stojite gledajući na nebo? Aleluja. Ovaj Isus, koji se od vas uznio na nebo., tako će doći, kao što ste gle dali da ide na nebo. Aleluja, aleluja, aleluja. (Ps. 46, 2) Svi narodi plješčite rukama, pokliknite Bogu glasom radosnim. Slava Ocu . . . Ljudi . . , <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 332–333 (snimka 167) (OCR)"},"421b4c9eb87b7fda":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da mi koji vjerujemo da je tvoj Jedinorođenac, naš Otkupitelj, na današnji dan uzašao na nebesa i sami budemo duhom uvijek u nebeskim stvarima.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da mi, koji vjerujemo, da je Jedinorođeni Tvoj, Otkupitelj naš, na današnji dan uzašao na nebesa, i sami duhom u nebesima obitavamo. Po istom Gospodinu . . .","knRef":"Kniewald 1942, str. 332–333 (snimka 167) (OCR)"},"fc8304657611db4a":{"t":"Dj 1, 1-11\nČitanje Djela apostolskih. Prvu sam knjigu, o Teofile, napisao o svemu što je Isus činio i učio od početka pa sve do onog dana, kad je uzašao na nebo, pošto je apostolima, koje je izabrao po Duhu Svetom, dao zapovijedi. On se poslije svoje muke pokazivao živ apostolima dajući im brojne dokaze, javljao im se četrdeset dana i govorio im o Božjem kraljevstvu. Kad je s njima jeo, rekao im je da ne odlaze iz Jeruzalema, nego da čekaju Očevo obećanje, Obećanje za koje ste, reče, čuli od mene: Ivan je krstio vodom, a vi ćete nedugo poslije ovih dana biti kršteni Duhom Svetim. Tada ga prisutni upitaju: Hoćeš li, Gospodine, sada obnoviti Izraelsko kraljevstvo? A on im odgovori: Nije vam potrebno znati vrijeme i prigodu što ih je Otac zadržao u svojoj vlasti. Nego ćete primiti silu Duha Svetoga i za mene ćete svjedočiti u Jeruzalemu, u čitavoj Judeji i Samariji i sve do kraja zemlje. I kad to reče, uzdigne se pred njima, a oblak ga zastre njihovim očima. A dok su oni promatrali, kako se uzdiže k nebu, stanu do njih dvojica obučena u bjelinu. Ovi im rekoše: Galilejci, što stojite i gledate u nebo? Ovaj Isus, koji je pred vašim očima uznesen na nebo, isto će tako sići kao što ste vidjeli da uzlazi na nebo.","kn":"Čitanje Djela apostolskih (I, 1-11). Prvo sam djelo, o Teofile, sastavio o svemu, što je Isus činio i učio od početka pa sve do dana, kad je uzašao davši zapovijedi apostolima, koje je izabrao po Duhu Svetomu. Njima se poslije svoje muke pokazivao živ u mnogo dokaza, javljao im se kroz četrdeset dana i govorio o kraljevstvu Božjem. I kad je bio s njima za stolom,, zapovjedi im, da ne idu iz Jeruzalema, nego da čekaju Očevo obećanje, koje ste čuli (reče) od mene. Jer istina, Ivan je krstio vodom, ali vi ćete biti kršteni Duhom Svetim ne dugo poslije ovih dana. A oni, koji su se bili sabrali, upitaše ga: Gospodine, hoćeš li sada obnoviti izraelsko kraljevstvo? On im odgovori: Vama ne treba znati vremena ili časova, koje je Otac ostavio u svojoj vlasti. Nego primit ćete silu Duha Svetoga, koji će doći na vas, i bit ćete mi svjedoci u Jeruzalemu, po cijeloj Judeji i Samariji i sve do kraja zemlje. I kad to izreče, diže se, dok su oni gledali, i uze ga oblak s njihovih očiju. I kad su gledali, kako ide na nebo, stadoše kraj njih dva čovjeka u bijelim haljinama, koji im rekoše: Ljudi Galilejci, što stojite i gledate na nebo? Ovaj Isus, koji je cd vas uzet na nebo, isto će tako doći, kako ste ga vidjeli da ide na nebo.","knRef":"Kniewald 1942, str. 332–333 (snimka 167) (OCR)"},"13bea69198da51ab":{"t":"Ps 46, 6, Ps 67, 18-19\n<i>Aleluja</i>, <i>aleluja</i>.\nUziđe Bog uz klicanje i Gospodin uz glas trublje, <i>aleluja</i>.\nGospodin sa Sinaja dolazi u svetište, uzlazi uvis i vodi sa sobom roblje, <i>aleluja</i>.","kn":"Alelnja, a-leluja (Ps. 46, 6). Uziđe Bog u kllcandu, i Grospodin uz glas trube, Aleluja. (P,s. 67, 18, 19) Gospodin na Sinaju u svetinji ulazi u visinu vodeći roblje. Aleluja.","knRef":"Kniewald 1942, str. 334–335 (snimka 168) (OCR)"},"66026265bfc28402":{"t":"Mk 16, 14-20\nSlijedi sveto Evanđelje po Marku. U ono vrijeme kad su jedanaestorica sjedila za stolom, ukaže im se Isus te ih prekori s njihove nevjere i tvrda srca, jer nisu vjerovali onima koji su ga vidjeli poslije uskrsnuća. Zatim im reče: Pođite po svemu svijetu i propovijedajte evanđelje svim stvorovima. Tko bude vjerovao i krsti se, spasit će se, a tko ne bude vjerovao, bit će osuđen. One koji budu vjerovali pratit će ova čudesa: u moje će ime izgoniti đavle, i govorit će nove jezike, hvatat će zmije, ako popiju što smrtonosno, neće im naškoditi, na bolesnike će polagati ruke i bolesnici će ozdravljati. I Gospodin Isus poslije govora s apostolima uznese se na nebo i sjede s desna Bogu. Oni su otišli i svuda su propovijedali, a pomagao im je Gospodin i njihovu je riječ potvrđivao čudesima koja su slijedila. [Nakon pročitanog Evanđelja ugasi se uskrsna svijeća]","kn":"t Slijedi sveto evanđelje po Marku (16, 14-20). U ono vrijeme ukaza se Isus jedanaiestorici, kad su sjedili za stolom, te ih prekori radi njihove nevjere i tvrda srca, jer inijesu vjerovali onima, koji su ga vidjeli, da je uskrsnuo. I reče im: Idite poi svemu svijetu i propovijedajte evanđelje svakomu stvoru. Tko bude vjerovao i pokrstio se, spasit će se, a tko ne bude vjerovao, osudit oe se. A one, koji budu vjerovali, pratit će ovi znakovi: U moje će ime Izgoniti đavle, govorit će novim jezicima, uzimat će zmije, i ako popiju što zadaje smrt, ne će ,im naškoditi, ruke će polagati na bolesnike, i oni će ozdravljati. I Gospodin Isus, kad im je to rekao, bi uzet na nebo i sjede Bogu s desne A oni su otišli i svagdje propovijedali, a Gospodin im je pomogao i čudesima, koja su slijedila, potru’đivao je njihove riječi.","knRef":"Kniewald 1942, str. 334–335 (snimka 168) (OCR)"},"95c349320dc6471f":{"t":"Ps 46, 6\nUzlazi Bog uz klicanje i Gospodin uz glas trublje, <i>aleluja</i>.","kn":"(Ps. 46, 6). Uziđe Bog u klicanju, Gospodin uz glas trube. Aleluja.","knRef":"Kniewald 1942, str. 334–335 (snimka 168) (OCR)"},"740dd5e53532ba98":{"t":"Primi, Gospodine, darove koje prinosimo o slavnom uzašašću tvojega Sina, i podaj milostivo, da se izbavimo od sadašnjih pogibli i prispijemo u vječni život.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, darove, što ih prinosimo o slavnom uzašašću Sina Tvojega, da se od sadašnjih pogibli oslobodimo i dopremo do vječnoga života, po istom Gospodinu . . .","knRef":"Kniewald 1942, str. 334–335 (snimka 168) (OCR)"},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje: Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospodinu našem, jer On se poslije svoga uskrsnuća očito ukazao svim svojim učenicima 1 njima se na očigled uzđignuo na nebo, da tako, po njegovom daru, budemo zajedničari Božanstva Njegova. I toga radi pjevamo pjesmu slave Tvoje s anđelima i B arkanđelima, s prijestolima i s gospodstvima, sa svom silom nebeske vojske bez prestanka govoreći:","knRef":"Kniewald 1942, str. 336–337 (snimka 169) (OCR)"},"d3e77cd03fac0df2":{"t":"Ps 67, 33-34\nPjevajte psalme Gospodinu koji uzlazi na najviša nebesa prema istoku, <i>aleluja</i>.","kn":"(Ps. 67, 33, 34). Pjevajte Gospodinu, koji uziđe nad nebesa, nebesa iskonska, alelujai, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 334–335 (snimka 168) (OCR)"},"6a69ef6d40822c62":{"t":"<i>Pomolimo se</i>.\nPodaj nam, molimo, svemogući i milosrdni Bože, da ono što si nam pod vidljivim otajstvima dao za hranu postignemo nevidljivim učinkom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj nam, molimo, svemogući i milostivi Bože, da primivši svetotajstva vidljivim načinom, postignemo nevidljivi učinak svetih tajna, po G. n.","knRef":"Kniewald 1942, str. 334–335 (snimka 168) (OCR)"}}});
